def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'C'
    if n == 4:
        return 'D'
    if n == 5:
        return 'C'
    opp_R6 = history[5][1]
    if opp_R6 == 'C':
        opp_def_after = 0
        for i in range(6, n):
            if history[i][1] == 'D':
                opp_def_after += 1
        if opp_def_after > 0:
            if n >= 99:
                return 'D'
            if history[-1][1] == 'D':
                return 'D'
            return 'C'
        if n >= 98:
            return 'D'
        if n % 3 == 0 and history[-1][0] == 'C':
            return 'D'
        return 'C'
    else:
        opp_def = 0
        for h in history:
            if h[1] == 'D':
                opp_def += 1
        if opp_def <= 1:
            if n >= 99:
                return 'D'
            return 'C'
        else:
            if n >= 99:
                return 'D'
            if history[-1][1] == 'D':
                return 'D'
            return 'C'
